package com.plantgrowth.forecasting.security;import jakarta.servlet.*;import jakarta.servlet.http.*;import org.springframework.security.authentication.*;import org.springframework.security.core.authority.*;import org.springframework.security.core.context.SecurityContextHolder;import org.springframework.stereotype.Component;import org.springframework.web.filter.OncePerRequestFilter;import io.jsonwebtoken.Claims;import java.io.*;import java.util.*;
@Component public class JwtFilter extends OncePerRequestFilter {private final JwtService jwt;public JwtFilter(JwtService jwt){this.jwt=jwt;}protected void doFilterInternal(HttpServletRequest r,HttpServletResponse s,FilterChain c)throws ServletException,IOException{String h=r.getHeader("Authorization");if(h!=null&&h.startsWith("Bearer "))try{Claims p=jwt.parse(h.substring(7));var a=new UsernamePasswordAuthenticationToken(p.get("uid",Long.class),null,List.of(new SimpleGrantedAuthority("ROLE_"+p.get("role",String.class))));SecurityContextHolder.getContext().setAuthentication(a);}catch(Exception ignored){}c.doFilter(r,s);}}
